 }
 if(String(field(o,['appointment_id','booking_id','id']))===id)return o;
 for(const k of ['body','data','appointments','appointment','bookings','booking','result','results','response','items','rows','records']){
  const r=encontrar(o[k],id,level+1);if(r)return r;
 }return null;
