}
function verificar(raw,expected,after=false){
 const code=Number(raw?.statusCode||0);const body=parse(raw?.body??raw);const c=encontrar(body,expected.appointment_id);const errors=[];let estadoObservado=null;
 if(raw?.error||code<200||code>=300||!body||body.status===false||body.success===false||body.error||['error','failed'].includes(norm(body.status)))errors.push('ERROR_PABAU');
 if(!c)errors.push('CITA_NO_ENCONTRADA');
 else{
  const st=field(c,['status','appointment_status','booking_status']);const status=norm(typeof st==='object'?st?.name:st);
  estadoObservado=typeof st==='object'?(st?.name??null):(st??null);
  if(!status)errors.push('ESTADO_NO_INFORMADO');
  if(c._cantidad_clientes!=null&&c._cantidad_clientes!==1)errors.push('CLIENTE_AMBIGUO');
  if(c._cantidad_servicios!=null&&c._cantidad_servicios!==1)errors.push('SERVICIO_AMBIGUO');
  if(/cancel|deleted|eliminad|expired|expirad|no.?show|complete|completad|arrived|running/.test(status)||[true,1,'1'].includes(c.deleted)||[true,1,'1'].includes(c.cancelled))errors.push('CITA_NO_VIGENTE');
  const client=String(field(c,['contact_id','client_id'])??'');if(client!==expected.esperado_cliente)errors.push('CLIENTE_NO_COINCIDE');
  const branch=String(field(c,['location_id','branch_id'])??c.location?.id??'');if(branch!==expected.esperado_sucursal)errors.push('SUCURSAL_NO_COINCIDE');
  const start=local(field(c,['start_date','start_datetime','start','start_time','StartDate','appointment_date']));if(start!==expected.esperado_inicio)errors.push('HORARIO_NO_COINCIDE');
  const svc=String(field(c,['service_id','service'])??'');if(svc!==expected.esperado_servicio)errors.push('SERVICIO_NO_COINCIDE');
  if(after&&(!contrato(expected.config)||String(pathValue(c,expected.config.ruta_lectura))!==String(expected.config.valor_lectura)))errors.push('ESTADO_CONFIRMADO_NO_VERIFICADO');
 }
