function revisarTodas(responses,expected,after=false){
 if(responses.length!==expected.length)return {ok:false,detalle:[{errores:['RESPUESTAS_INCOMPLETAS']}]};
 const detail=expected.map((e,i)=>verificar(responses[i]?.json??responses[i],e,after));
