const base = { ...original };
if (original.body && typeof original.body === 'object' && !Array.isArray(original.body)) Object.assign(base, original.body);
if (typeof base.query === 'string') { try { Object.assign(base, JSON.parse(base.query)); } catch {} }
else if (base.query && typeof base.query === 'object' && !Array.isArray(base.query)) Object.assign(base, base.query);

const limpiar = v => (v === undefined || v === null) ? '' : String(v).trim();
const norm = v => limpiar(v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');

function buscar(alias) {
  for (const a of alias) {
    const clave = Object.keys(base).find(k => norm(k) === norm(a));
    if (clave !== undefined && limpiar(base[clave]) !== '') return limpiar(base[clave]);
  }
  return '';
}

